#!/usr/bin/env python3\n\"\"\"\nPassword strength analyzer.\nAccepts a password via command line argument or stdin and prints JSON with analysis.\n\"\"\"\n\nimport sys\nimport json\nimport argparse\nimport math\nimport string\n\ndef estimate_entropy(pwd):\n    pool = 0\n    if any(c.islower() for c in pwd):\n        pool += 26\n    if any(c.isupper() for c in pwd):\n        pool += 26\n    if any(c.isdigit() for c in pwd):\n        pool += 10\n    if any(c in string.punctuation for c in pwd):\n        pool += len(string.punctuation)\n    if any(c not in string.printable for c in pwd):\n        pool += 32\n    if pool == 0:\n        return 0\n    return len(pwd) * math.log2(pool)\n\ndef analyze(pwd):\n    length = len(pwd)\n    entropy = estimate_entropy(pwd)\n    score = min(100, int(entropy * 2))\n    suggestions = []\n    if length < 8:\n        suggestions.append(\"اجعل كلمة السر أطول من 8 أحرف\")\n    if not any(c.islower() for c in pwd):\n        suggestions.append(\"استخدم أحرف صغيرة\")\n    if not any(c.isupper() for c in pwd):\n        suggestions.append(\"استخدم أحرف كبيرة\")\n    if not any(c.isdigit() for c in pwd):\n        suggestions.append(\"استخدم أرقام\")\n    if not any(c in string.punctuation for c in pwd):\n        suggestions.append(\"استخدم رموز خاصة\")\n    return {\n        \"length\": length,\n        \"entropy_bits\": round(entropy, 2),\n        \"score\": score,\n        \"suggestions\": suggestions\n    }\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Password strength analyzer\")\n    parser.add_argument(\"password\", nargs=\"?\", help=\"Password to analyze\")\n    args = parser.parse_args()\n    pwd = args.password\n    if pwd is None:\n        pwd = sys.stdin.read().strip()\n    result = analyze(pwd)\n    json.dump(result, sys.stdout, ensure_ascii=False)\n    sys.stdout.write(\"\\n\")\n\nif __name__ == \"__main__\":\n    main()